package main

import (
	"fmt"
	"html"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail generates a MIME-formatted HTML email string containing user feedback.
// The returned string is structured according to RFC 5322 and is fully compatible 
// with the msg parameter of net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate required fields
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("invalid input: all fields are required")
	}

	// Escape HTML special characters to prevent injection and rendering issues
	safeUserName := html.EscapeString(userName)
	safeSubject := html.EscapeString(subject)
	safeContent := html.EscapeString(feedbackContent)

	// HTML email template with inline CSS for maximum email client compatibility
	htmlTemplate := `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>User Feedback</title>
    <style>
        body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f7f6; margin: 0; padding: 20px; color: #333; }
        .container { max-width: 600px; margin: 0 auto; background-color: #ffffff; padding: 24px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.05); }
        h2 { color: #2c3e50; border-bottom: 2px solid #3498db; padding-bottom: 10px; margin-top: 0; }
        .field { margin-bottom: 16px; }
        .label { font-weight: 600; color: #555; display: block; margin-bottom: 6px; font-size: 14px; }
        .value { background-color: #f8f9fa; padding: 12px; border-radius: 6px; border: 1px solid #e9ecef; font-size: 14px; line-height: 1.5; white-space: pre-wrap; word-wrap: break-word; }
        .footer { margin-top: 20px; font-size: 12px; color: #888; text-align: center; }
    </style>
</head>
<body>
    <div class="container">
        <h2>New User Feedback</h2>
        <div class="field">
            <span class="label">Username:</span>
            <span class="value">%s</span>
        </div>
        <div class="field">
            <span class="label">Subject:</span>
            <span class="value">%s</span>
        </div>
        <div class="field">
            <span class="label">Feedback Content:</span>
            <div class="value">%s</div>
        </div>
        <div class="footer">This email was automatically generated by the feedback system.</div>
    </div>
</body>
</html>`

	htmlBody := fmt.Sprintf(htmlTemplate, safeUserName, safeSubject, safeContent)

	// Construct MIME headers compatible with net/smtp
	var msg strings.Builder
	msg.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", subject))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"UTF-8\"\r\n")
	msg.WriteString("\r\n") // Mandatory separator between headers and body
	msg.WriteString(htmlBody)

	return msg.String(), nil
}

func main() {
	// Example usage
	from := "noreply@example.com"
	to := "support@example.com"
	user := "JohnDoe"
	subj := "Login Page Error"
	content := "I am unable to log in. The page returns a 500 error after submitting credentials.\nPlease investigate."

	emailBody, err := BuildFeedbackEmail(from, to, user, subj, content)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Println("Generated Email Content:")
	fmt.Println(strings.Repeat("=", 60))
	fmt.Println(emailBody)
	fmt.Println(strings.Repeat("=", 60))

	// The generated emailBody is ready to be passed directly to net/smtp.SendMail
	// Example integration with net/smtp:
	// auth := smtp.PlainAuth("", from, "your_password", "smtp.example.com")
	// err = smtp.SendMail("smtp.example.com:587", auth, from, []string{to}, []byte(emailBody))
	_ = smtp.SendMail // Reference to satisfy import and demonstrate intended package usage
}

