	}

	// Security Fix 1: Prevent Email Header Injection (CRLF Injection)
	// Sanitize the subject by stripping carriage returns and newlines before placing it in headers
	safeSubjectHeader := strings.NewReplacer("\r", " ", "\n", " ").Replace(subject)
	emailSubject := fmt.Sprintf("Feedback: %s", safeSubjectHeader)

	// Construct email headers
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n",
