// BuildFeedbackEmail constructs a MIME-formatted email string containing user feedback.
// The output is fully compatible with net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Parse the HTML template
	tmpl, err := template.New("feedbackEmail").Parse(feedbackHTMLTemplate)
	if err != nil {
		return "", fmt.Errorf("failed to parse email template: %w", err)
	}

	// Execute template with user-submitted data
	var htmlBuf bytes.Buffer
	err = tmpl.Execute(&htmlBuf, map[string]string{
		"UserName": userName,
		"Subject":  subject,
		"Content":  feedbackContent,
	})
	if err != nil {
		return "", fmt.Errorf("failed to render email template: %w", err)
	}

	// Construct RFC 5322 compliant message with MIME headers
	// Uses \r\n line endings as required by SMTP standards
	msg := fmt.Sprintf("From: %s\r\n"+
