		"Subject: %s\r\n"+
		"MIME-Version: 1.0\r\n"+
		"Content-Type: text/html; charset=\"UTF-8\"\r\n\r\n"+
		"%s",
		fromAddr, toAddr, subject, htmlBuf.String())

	return msg, nil
}

