package main

import (
	"fmt"
	"html"
	"strings"
)

// BuildFeedbackEmail constructs a raw MIME email message containing user feedback.
// The output format is specifically designed to be passed directly to net/smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	if fromAddr == "" || toAddr == "" {
		return "", fmt.Errorf("sender and recipient addresses cannot be empty")
	}

	// Escape HTML to prevent injection and ensure valid rendering
	safeUser := html.EscapeString(userName)
	safeSubject := html.EscapeString(subject)
	safeContent := html.EscapeString(feedbackContent)
	// Preserve user line breaks in HTML format
	safeContent = strings.ReplaceAll(safeContent, "\n", "<br>")

	// HTML template for the email body
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>User Feedback</title>
</head>
<body>
    <h2>New User Feedback Submission</h2>
    <p><strong>Username:</strong> %s</p>
    <p><strong>Subject:</strong> %s</p>
    <p><strong>Feedback Content:</strong></p>
    <div style="background-color: #f9f9f9; padding: 10px; border: 1px solid #ddd; border-radius: 4px;">
        %s
    </div>
</body>
</html>`, safeUser, safeSubject, safeContent)

	// Construct raw MIME message compliant with RFC 5322 for net/smtp
	// SMTP protocol requires CRLF (\r\n) line endings for headers
	var msg strings.Builder
	msg.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	msg.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	msg.WriteString(fmt.Sprintf("Subject: %s\r\n", subject))
	msg.WriteString("MIME-Version: 1.0\r\n")
	msg.WriteString("Content-Type: text/html; charset=\"UTF-8\"\r\n")
	msg.WriteString("\r\n")
	msg.WriteString(htmlBody)

	return msg.String(), nil
}

func main() {
	// Example usage demonstrating the feedback email generation
	from := "noreply@example.com"
	to := "support@example.com"
	user := "Alice"
	subj := "Feature Request"
	content := "Please add a dark mode to the dashboard.\nIt would greatly improve usability at night."

	email, err := BuildFeedbackEmail(from, to, user, subj, content)
	if err != nil {
		fmt.Printf("Failed to build email: %v\n", err)
		return
	}

	fmt.Println("Generated Email Content:")
	fmt.Println(email)
}

